def data(s,x,title,nodeid,store=False):
 y=685;w=250;h=88
 if store:
  s.add(f'<path d="M{x},{y+15} C{x},{y-5} {x+w},{y-5} {x+w},{y+15} V{y+h-15} C{x+w},{y+h+5} {x},{y+h+5} {x},{y+h-15} Z" fill="{GREEN}" stroke="black" stroke-width="2"/>')
  s.add(f'<ellipse cx="{x+w/2}" cy="{y+15}" rx="{w/2}" ry="15" fill="none" stroke="black" stroke-width="2"/>')
 else:
  s.add(f'<path d="M{x},{y} H{x+w-18} L{x+w},{y+18} V{y+h} H{x} Z M{x+w-18},{y} V{y+18} H{x+w}" fill="white" stroke="black" stroke-width="2"/>')
 s.text(x+w/2,y+h/2+7,title,21,w-24)
 nx,ny,nw,nh=s.nodes[nodeid]
 s.add(f'<polyline points="{nx+nw/2},{ny+nh} {x+w/2},{y}" fill="none" stroke="black" stroke-width="1.6" stroke-dasharray="4 5" marker-end="url(#dataArrow)"/>')
 s.data_count+=1

def process(spec):
 name,role,command,check,operation,result,check_ops,op_ops,docs,note=spec
 s=BPMN(name,[role,'Банковская система'],2200,900)
 s.add('<defs><marker id="dataArrow" markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto"><path d="M1,1 L9,5 L1,9" fill="none" stroke="black" stroke-width="1.4"/></marker></defs>')
 s.event('s',145,0,'Обращение');s.task('cmd',235,0,command,285,user=True)
 s.task('check',565,1,check,265);s.gateway('allow',885,1,'Допустимо?')
 s.task('op',1040,1,operation,320,sub=True);s.gateway('ok',1420,1,'Успешно?')
 s.task('result',1650,0,result,300,user=True);s.event('e',2090,0,'Завершено',True)
 s.task('error',1050,0,'Прочитать отказ\nи текущее состояние',300,user=True);s.event('no',1450,0,'Отклонено',True)
 s.link('s','cmd');s.link('cmd','check');s.link('check','allow');s.link('allow','op','да');s.link('op','ok')
 s.link('ok','result','да',route=[(1550,599),(1550,216)]);s.link('result','e');s.link('error','no')
 s.link('allow','error','нет',source='top',target='bottom',route=[(919,330),(1200,330)],labelpos=(945,350))
 s.link('ok','error','нет',source='top',target='bottom',route=[(1454,430),(1260,430),(1260,330),(1200,330)],labelpos=(1510,400))
 for nodeid,ops in [('check',check_ops),('op',op_ops)]:
  if ops:
   x,y,w,h=s.nodes[nodeid];s.text(x+w/2,y-22,', '.join(ops),21,420,bg=True);s.operations.update(ops)
 data(s,565,docs[0],'check');data(s,1075,docs[1],'op',True)
 return s.finish(note)

def all_processes():
 from detailed_process_figures import BUILDERS
 return [BUILDERS[spec[0]]() if spec[0] in BUILDERS else process(spec) for spec in SPECS]
